using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, patterns, and quantitative reasoning." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Understanding the fundamental laws governing the natural world." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, societies, and civilizations." },
            new() { Id = 6, Code = "BIOL", Name = "Biology", Description = "Study of living organisms and life processes." },
        ];

        _courses =
        [
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science. Topics include problem solving, computational thinking, data representation, and an introduction to programming using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a PhD from MIT and has 15 years of experience in computer science education. Her research focuses on programming language design.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes analysis of time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez is an expert in algorithm optimization with publications in top-tier journals. He previously worked at Google Research.", DepartmentId = 1 },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational database systems. Topics include the relational model, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 1:00–2:15 PM", InstructorName = "Dr. Carol Singh", InstructorBio = "Dr. Singh specializes in distributed database systems and has contributed to several open-source database projects.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 4, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Students will complete hands-on projects using popular ML frameworks.", Credits = 4, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a PhD from MIT and has 15 years of experience in computer science education. Her research focuses on programming language design.", DepartmentId = 1 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, differentiation, and an introduction to integration. Applications to physics, engineering, and the natural sciences.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning educator with a passion for making calculus accessible. He has authored two widely-used textbooks.", DepartmentId = 2, IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues and eigenvectors, with applications in data science and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov researches algebraic topology and has been teaching linear algebra for over a decade.", DepartmentId = 2 },
            new() { Id = 7, Code = "MATH 340", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, statistical inference, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 3:00–4:15 PM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning educator with a passion for making calculus accessible. He has authored two widely-used textbooks.", DepartmentId = 2 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions where students conduct experiments and analyze data.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Frank Müller", InstructorBio = "Dr. Müller is an experimental physicist who previously worked at CERN. He brings real-world research experience into the classroom.", DepartmentId = 3, IsFeatured = true },
            new() { Id = 9, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continues the laboratory component from Physics I.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Grace Okafor", InstructorBio = "Dr. Okafor's research explores quantum optics. She is a recipient of the National Science Foundation CAREER Award.", DepartmentId = 3 },

